//! Numbers from scipy 1.18.1 for the distribution fit, the probability plot, the noncentral t and F distributions
//! and the power calculations (made by tools/stats-dist-ref.py). Do not edit by hand. These numbers come from
//! scipy, not from Origin.
#![allow(clippy::excessive_precision, dead_code)]

/// `family` is the index into norm, lognorm, expon, gamma, weibull_min. `params_scipy` is what scipy.stats.<dist>.fit
/// returned (loc fixed at 0); `params` is the same estimate with the shape solved to machine precision.
pub struct FitCase {
    pub name: &'static str,
    pub family: usize,
    pub data: &'static [f64],
    pub params_scipy: &'static [f64],
    pub params: &'static [f64],
    pub log_likelihood: f64,
    pub aic: f64,
    pub bic: f64,
    pub ks_d: f64,
    pub ks_p: f64,
    pub ad: f64,
}
pub struct ProbCase {
    pub name: &'static str,
    pub family: usize,
    pub data: &'static [f64],
    /// The shape passed to scipy.stats.probplot (NaN for the families without one).
    pub shape: f64,
    pub theoretical: &'static [f64],
    pub ordered: &'static [f64],
    pub slope: f64,
    pub intercept: f64,
    pub r: f64,
}
/// `p` is P(D_n >= d) of the two-sided Kolmogorov statistic, `scipy.stats.kstwo.sf(d, n)`.
pub struct KsCase {
    pub n: usize,
    pub d: f64,
    pub p: f64,
}
pub struct NctCase {
    pub t: f64,
    pub df: f64,
    pub ncp: f64,
    pub cdf: f64,
    pub sf: f64,
}
pub struct NcfCase {
    pub x: f64,
    pub df1: f64,
    pub df2: f64,
    pub ncp: f64,
    pub cdf: f64,
    pub sf: f64,
}
/// design: 0 one sample, 1 paired, 2 two samples (`ratio` = n2 / n1); tail: 0 two-sided, 1 upper.
pub struct TPowerCase {
    pub design: u8,
    pub ratio: f64,
    pub effect: f64,
    pub n1: usize,
    pub alpha: f64,
    pub tail: u8,
    pub n2: usize,
    pub df: f64,
    pub ncp: f64,
    pub critical: f64,
    pub power: f64,
}
pub struct TSizeCase {
    pub design: u8,
    pub ratio: f64,
    pub effect: f64,
    pub target: f64,
    pub alpha: f64,
    pub tail: u8,
    pub n: usize,
    pub n2: usize,
    pub power: f64,
}
pub struct AnovaPowerCase {
    pub groups: usize,
    pub effect: f64,
    pub n: usize,
    pub alpha: f64,
    pub df1: f64,
    pub df2: f64,
    pub ncp: f64,
    pub critical: f64,
    pub power: f64,
}
pub struct AnovaSizeCase {
    pub groups: usize,
    pub effect: f64,
    pub target: f64,
    pub alpha: f64,
    pub n: usize,
    pub power: f64,
}

